mapper.select:
SELECT COUNT(t_price_bidding.id)
FROM t_price_bidding
WHERE t_price_bidding.tender_number = #{tenderNumber}

SELECT t_price_bidding.latest_quotation
FROM t_price_bidding
WHERE t_price_bidding.tender_number = #{tenderNumber}

SELECT t_sales_bidding.delay_frequency AS delayFrequency
FROM t_sales_bidding
WHERE t_sales_bidding.tender_number = #{tenderNumber}

mapper.update:
UPDATE t_sales_bidding
SET t_sales_bidding.bidding_duration = #{biddingDuration},
    t_sales_bidding.delay_frequency  = #{delayFrequency}
WHERE t_sales_bidding.tender_number = #{tenderNumber}

UPDATE t_price_bidding
SET t_price_bidding.status = #{entity.status}
WHERE t_price_bidding.id = #{entity.id}
